"""Human-readable guide; OpenAPI and Swagger UI are generated by FastAPI."""

import json
from html import escape
from importlib.resources import files
from string import Template

from .config import WebhookSettings

EXAMPLE = {
    "texts": {"instruction": "画像について説明してください", "language": "日本語"},
    "images": {
        "before": {
            "filename": "before.png",
            "content_type": "image/png",
            "content_base64": (
                "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk"
                "+A8AAQUBAScY42YAAAAASUVORK5CYII="
            ),
        }
    },
}


def description(settings: WebhookSettings) -> str:
    return (
        "名前付きテキスト・画像を送り、コールバックの推論結果を取得するAPIです。\n\n"
        "[送信例と結果の読み方（オフライン対応ガイド）](/guide)\n\n"
        f"入力本文は最大 {settings.max_body_bytes} バイト、"
        f"合計 {settings.max_items} 項目です。"
        f"結果は最大 {settings.max_result_bytes} バイト（JSON・Base64込み）。\n\n"
        f"POSTは既定で最大 {settings.response_timeout} 秒待機します。"
        "201は完了した結果、202は待機上限を超えた保留状態を表します。"
        "?wait=false は結果を待たず201でイベントを作成します。"
        "GETでstatusとresultを確認できます。\n\n"
        f"最大 {settings.history_size} 件の結果をメモリ保持します。"
        "未完了イベントは追い出しません。全件が未完了なら503になります。"
        "停止で履歴は消去されます。自動再送・重複排除はありません。"
    )


def render_docs(settings: WebhookSettings, base_url: str) -> str:
    template = Template(
        files(__package__).joinpath("docs.html").read_text(encoding="utf-8")
    )
    values = {
        "endpoint": base_url + settings.path,
        "endpoint_literal": json.dumps(base_url + settings.path),
        "path": settings.path,
        "max_body_bytes": str(settings.max_body_bytes),
        "max_result_bytes": str(settings.max_result_bytes),
        "max_items": str(settings.max_items),
        "history_size": str(settings.history_size),
        "request_timeout": str(settings.request_timeout),
        "response_timeout": str(settings.response_timeout),
        "client_timeout": str(settings.response_timeout + 5),
        "auth_description": (
            "送信・結果取得には Authorization: Bearer YOUR_TOKEN が必要です。"
            if settings.token is not None
            else "この受信口では認証トークンは設定されていません。"
        ),
        "auth_python": 'headers={"Authorization": "Bearer YOUR_TOKEN"},\n    '
        if settings.token
        else "",
        "auth_curl": ' -H "Authorization: Bearer YOUR_TOKEN"' if settings.token else "",
        "example": json.dumps(EXAMPLE, ensure_ascii=False, indent=2),
    }
    return template.substitute({key: escape(value) for key, value in values.items()})
